using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 breaking change #1: Discriminator property renamed from
            // "Discriminator" to "$type". Our 500K existing documents and direct
            // SQL queries use the old name, so we must preserve it.
            entity.HasDiscriminatorInJsonProperty("Discriminator");

            // EF Core 9 breaking change #2: Id format changed from
            // "EntityType|KeyValue" (e.g. "Product|123") to just "KeyValue".
            // Existing documents use the old format, so we must preserve it.
            entity.HasIdPropertyInJsonProperty("id");
            entity.Property(p => p.Id)
                  .ToJsonProperty("Id")
                  .HasValueGenerator<Microsoft.EntityFrameworkCore.Cosmos.ValueGeneration.IdValueGenerator>();

            // EF Core 9 breaking change #3: HasIndex is no longer supported for
            // Cosmos provider — Cosmos uses server-side indexing policies, not
            // client-side indexes. Removed the previous HasIndex(p => p.Sku) call.
        });
    }

    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
    {
        // Preserve the EF Core 8 id format "EntityType|KeyValue" globally.
        configurationBuilder.Conventions.Add(_ =>
            new Microsoft.EntityFrameworkCore.Cosmos.Metadata.Conventions.IdValueGeneratorConvention());
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

