class CosmosQuery
{
    async Task FindProductsAsync(ProductContext ctx)
    {
        // Direct Cosmos SQL — still uses c.Discriminator because we configured
        // HasDiscriminatorInJsonProperty("Discriminator") in OnModelCreating.
        var sql = "SELECT * FROM c WHERE c.Discriminator = 'Product' AND c.Sku = @sku";

        // EF Core 9 breaking change #4: Synchronous LINQ operators (ToList,
        // First, Count, etc.) are no longer supported by the Cosmos provider.
        // All queries must use async equivalents.
        var products = await ctx.Products.Where(p => p.Sku == "ABC").ToListAsync();
    }
}

